export interface ConnectorConfig {
  /** Notion integration token (Bearer). Expected env var: NOTION_TOKEN */
  notionToken: string
  /** Notion database ID for the 'Signed' database */
  databaseId: string
  /** Injected fetch for testing; defaults to global fetch */
  fetch?: typeof fetch
}

export interface PipedriveDealWebhook {
  data: {
    id: number
    title: string
    value: number
    currency: string
    owner_id: {
      id: number
      name: string
    }
    won_time: string
    stage_id: number
    status: string
  }
  previous: unknown
  meta: {
    action: string
    entity: string
    entity_id: string
    timestamp: string
    version: string
  }
}

export interface HandleResult {
  pageId: string
  notionPageUrl: string
}

function validatePayload(payload: PipedriveDealWebhook): void {
  if (!payload?.data) throw new Error('Missing required field: data')
  if (!payload.data.title) throw new Error('Missing required field: data.title')
  if (payload.data.value === undefined || payload.data.value === null) throw new Error('Missing required field: data.value')
  if (!payload.data.owner_id?.name) throw new Error('Missing required field: data.owner_id.name')
  if (!payload.data.won_time) throw new Error('Missing required field: data.won_time')
  if (payload.data.status !== 'won') throw new Error('Deal status is not "won"; ignoring')
}

function buildNotionPageBody(payload: PipedriveDealWebhook, databaseId: string): unknown {
  const deal = payload.data
  const closeDate = deal.won_time.split('T')[0] // YYYY-MM-DD

  return {
    parent: { database_id: databaseId },
    properties: {
      'Deal Name': {
        title: [{ text: { content: deal.title } }]
      },
      'Deal Value': {
        number: deal.value
      },
      Owner: {
        rich_text: [{ text: { content: deal.owner_id.name } }]
      },
      'Close Date': {
        date: { start: closeDate }
      }
    }
  }
}

export async function handle(payload: PipedriveDealWebhook, config: ConnectorConfig): Promise<HandleResult> {
  validatePayload(payload)

  const fetchImpl = config.fetch ?? fetch
  const body = buildNotionPageBody(payload, config.databaseId)

  const response = await fetchImpl('https://api.notion.com/v1/pages', {
    method: 'POST',
    headers: {
      Authorization: `Bearer ${config.notionToken}`,
      'Content-Type': 'application/json',
      'Notion-Version': '2022-06-28'
    },
    body: JSON.stringify(body)
  })

  if (!response.ok) {
    const text = await response.text().catch(() => '')
    throw new Error(`Notion API error: ${response.status} ${response.statusText} at POST https://api.notion.com/v1/pages - ${text}`)
  }

  const result = (await response.json()) as { id: string; url: string }
  return {
    pageId: result.id,
    notionPageUrl: result.url
  }
}

