  const deal = payload.data
  const closeDate = deal.won_time.split('T')[0] // YYYY-MM-DD

  return {
    parent: { database_id: databaseId },
    properties: {
      'Deal Name': {
        title: [{ text: { content: deal.title } }]
      },
      'Deal Value': {
        number: deal.value
      },
      Owner: {
        rich_text: [{ text: { content: deal.owner_id.name } }]
      },
